mapper.select:
SELECT u.user_id AS value,CONCAT(u.nick_name,' (',u.user_name,')') AS label FROM sys_user u WHERE u.status='0' AND u.del_flag='0'
AND (#{q.unrestricted}=TRUE OR u.user_id=#{q.selfUserId}

    OR u.dept_id IN #{id}
)
AND (u.nick_name LIKE CONCAT('%',#{q.keyword},'%') OR u.user_name LIKE CONCAT('%',#{q.keyword},'%'))

    AND EXISTS(SELECT 1 FROM sys_user_role ur JOIN sys_role r ON r.role_id=ur.role_id
    JOIN sys_role_menu rm ON rm.role_id=r.role_id JOIN sys_menu m ON m.menu_id=rm.menu_id
    WHERE ur.user_id=u.user_id AND r.status='0' AND r.del_flag='0' AND m.status='0' AND m.perms=#{taskPermission})

ORDER BY u.user_id LIMIT 200

SELECT location_id AS value,CONCAT(location_name,' (',location_code,')') AS label FROM ca_location
WHERE status='0' AND (dept_id IS NULL OR #{q.unrestricted}=TRUE

    OR dept_id IN #{id}
) ORDER BY order_num,location_id

SELECT asset_id AS value,CONCAT(asset_code,' · ',asset_name) AS label FROM ca_asset
WHERE asset_status!='3'
AND (#{q.unrestricted}=TRUE OR keeper_user_id=#{q.selfUserId}

    OR dept_id IN #{id}
)
AND (asset_code LIKE CONCAT('%',#{q.keyword},'%') OR asset_name LIKE CONCAT('%',#{q.keyword},'%'))
ORDER BY asset_id DESC LIMIT 200
